import Combine
import Foundation
import DamageKit

/// The compact index generated by `scripts/build_native_damage_data.py`.
/// It deliberately mirrors the website's Chinese weapon labels, but it is
/// plain JSON consumed by Swift — not a WebView payload.
struct NativeDamageWeaponEntry: Decodable, Identifiable, Hashable {
    let n: String
    let z: String
    let c: String
    let t: String
    let img: String
    let mr: Int
    let atk: [String]
    let inc: Bool

    var id: String { n }

    var categoryLabel: String {
        switch c {
        case "Primary": return "主武器"
        case "Secondary": return "副武器"
        case "Melee": return "近战"
        case "Archgun": return "Archwing 枪械"
        case "Exalted Weapon": return "显赫武器"
        default: return c
        }
    }

    var iconURL: URL? {
        guard !img.isEmpty else { return nil }
        return URL(string: "https://warframe-damage.com/data/img/\(img)")
    }
}

/// Read-only catalogue shared by the native calculator pages.
///
/// The data directory is a folder reference in the app bundle, so weapon JSON
/// files keep their names and DataStore can use the same lookup it uses in the
/// command-line verifier.  No JavaScript, local HTTP server, or WebKit is
/// involved after this point.
@MainActor
final class NativeDamageCatalog: ObservableObject {
    static let shared = NativeDamageCatalog()

    @Published private(set) var weapons: [NativeDamageWeaponEntry] = []
    @Published private(set) var enemies: [Enemy] = []
    @Published private(set) var translations: [String: String] = [:]
    @Published private(set) var loadError: String?

    private(set) var store: DataStore?

    private init() {
        load()
    }

    func load() {
        guard let root = Bundle.main.url(forResource: "DamageData", withExtension: nil) else {
            loadError = "App 包里缺少原生计算数据（DamageData）"
            return
        }

        do {
            let decoder = JSONDecoder()
            let weaponData = try Data(contentsOf: root.appendingPathComponent("weapons-list.json"))
            let enemyData = try Data(contentsOf: root.appendingPathComponent("data/json/enemies-min.json"))
            let localizationData = try Data(contentsOf: root.appendingPathComponent("zh-Hans.json"))
            weapons = try decoder.decode([NativeDamageWeaponEntry].self, from: weaponData)
            enemies = try decoder.decode([Enemy].self, from: enemyData)
            translations = try decoder.decode([String: String].self, from: localizationData)
            store = DataStore(root: root)
            loadError = nil
        } catch {
            store = nil
            loadError = "原生计算数据读取失败：\(error.localizedDescription)"
        }
    }

    func local(_ english: String) -> String {
        translations[english] ?? english
    }

    func weapon(named name: String) throws -> Weapon {
        guard let store else { throw DamageKitError.missingResource("DamageData") }
        return try store.weapon(named: name)
    }

    func enemy(named name: String) throws -> Enemy {
        guard let store else { throw DamageKitError.missingResource("DamageData") }
        return try store.enemy(named: name)
    }

    /// The same tag intersection the site uses to filter its picker.  Formula
    /// validation still happens in DamageKit; this only prevents a primary Mod
    /// from cluttering a secondary weapon's list.
    func accepts(_ mod: ModDefinition, weapon: Weapon) -> Bool {
        guard let tags = mod.tags, !tags.isEmpty else { return true }
        var keys: Set<String> = [normalize(weapon.name)]
        for value in weapon.categories ?? [] { keys.insert(normalize(value)) }
        for value in weapon.compTags ?? [] { keys.insert(normalize(value)) }
        if let value = weapon.category { keys.insert(normalize(value)) }
        if let value = weapon.type { keys.insert(normalize(value)) }
        return tags.contains { keys.contains(normalize($0)) }
    }

    /// The site resolves Mod record image names through `/getImg.php`, which
    /// currently returns `/data/mods/<name>` (not `/data/img`).  The app first
    /// uses its bundled copy below; this URL is only a network fallback for a
    /// deliberately missing upstream image.
    func iconURL(for mod: ModDefinition) -> URL? {
        guard let image = mod.image, !image.isEmpty else { return nil }
        return URL(string: "https://warframe-damage.com/data/mods/\(image)")
    }

    func localWeaponIcon(named image: String) -> URL? {
        guard !image.isEmpty,
              let root = Bundle.main.url(forResource: "DamageData", withExtension: nil) else { return nil }
        let url = root.appendingPathComponent("icons").appendingPathComponent(image)
        return FileManager.default.fileExists(atPath: url.path) ? url : nil
    }

    func localModIcon(named image: String?) -> URL? {
        guard let image, !image.isEmpty,
              let root = Bundle.main.url(forResource: "DamageData", withExtension: nil) else { return nil }
        let url = root.appendingPathComponent("mod-icons").appendingPathComponent(image)
        return FileManager.default.fileExists(atPath: url.path) ? url : nil
    }

    func localModIcon(for mod: ModDefinition) -> URL? {
        localModIcon(named: mod.image)
    }

    private func normalize(_ value: String) -> String {
        value.lowercased().filter { $0.isLetter || $0.isNumber }
    }
}
